#include <dirent.h>
#include <errno.h>

char *get_ls_result(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        return strdup("");
    }

    char *result = NULL;
    size_t result_len = 0;
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        closedir(dir);
        return strdup("");
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        size_t len = strlen(entry->d_name);
        if (result_len + len + 1 > buffer_size) {
            buffer_size *= 2;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                free(buffer);
                closedir(dir);
                return strdup("");
            }
            buffer = new_buffer;
        }
        strcpy(buffer + result_len, entry->d_name);
        result_len += len;
        if (result_len < buffer_size - 1) {
            buffer[result_len] = '\n';
            result_len++;
        } else {
            buffer[result_len] = '\0';
        }
    }

    free(buffer);
    closedir(dir);

    char *final_result = malloc(result_len + 1);
    if (!final_result) {
        return strdup("");
    }
    memcpy(final_result, buffer, result_len + 1);
    return final_result;
}
